namespace ghidra.app.plugin.core.debug.gui.tracecalltree;



using docking.widgets.gtreetable;
using ghidra.trace.model.time;
using ghidra.util;
using resources;

public abstract class AbstractTraceCallTreeNode : GTreeTableNode {
	public record ParamNameToBytes(string name, byte[] bytes) {}

	private TraceSnapshot snap;
	private List<ParamNameToBytes> parameters;
	private byte[] returnVal;
	private string module;
	private int largestParamSize = 0;

	public AbstractTraceCallTreeNode(string name, string module,
			TraceSnapshot snap, List<ParamNameToBytes> parameters, byte[] returnVal) : base(name)
    {
		icon = Icons.RIGHT_ICON;
		this.snap = snap;
		this.parameters = parameters;
		this.returnVal = returnVal;
		this.module = module;
	}

	public int getLargestParamSize() {
		return largestParamSize;
	}

	public string getModule() {
		return module;
	}

	public ParamNameToBytes getParameter(int i) {
		if ((parameters != null) && (i >= 0) && (i < parameters.size())) {
			return parameters.get(i);
		}
		return null;
	}

	public int getParameterNumber() {
		return parameters.size();
	}

	public List<ParamNameToBytes> getParameters() {
		return parameters;
	}

	public string getParameterString(int i) {
		if ((parameters != null) && (i >= 0) && (i < parameters.size())) {
			return "%s: %s".formatted(parameters.get(i).name,
				NumericUtilities.convertBytesToString(parameters.get(i).bytes));
		}
		return "";
	}

	public byte[] getReturnVal() {
		return returnVal;
	}

